const assert=require('assert'),fs=require('fs'),path=require('path'),{execFileSync}=require('child_process');
const root=path.resolve(__dirname,'..'),runtime=['core.js','bookings.js','staffing.js','access.js','calendar.js','billing.js','viewer-access.js'];
execFileSync(process.execPath,[path.join(root,'scripts/build-bundles.js')],{cwd:root,stdio:'inherit'});const manifest=JSON.parse(fs.readFileSync(path.join(root,'dist/runtime-manifest.json'),'utf8'));assert.strictEqual(manifest.bundleCount,7);assert.strictEqual(manifest.sourceCount,7);assert.deepStrictEqual(manifest.bundles,runtime);assert.strictEqual(fs.readdirSync(root).filter(f=>/^app-\d+\.js$/.test(f)).length,0,'legacy app-N files remain');
const index=fs.readFileSync(path.join(root,'index.html'),'utf8');for(const file of runtime){assert(index.includes('<script src="'+file+'"></script>'),'index missing '+file);execFileSync(process.execPath,['--check',path.join(root,file)],{stdio:'pipe'});}assert(!index.includes('app-15.js'),'legacy entry point remains');const combined=runtime.map(f=>fs.readFileSync(path.join(root,f),'utf8')).join('\n');assert(combined.includes('OpsLifecycle.use('),'flattened lifecycle registry missing');assert(!combined.includes("const chain=['app-16.js'"),'legacy dynamic loader remains');
const builtCore=fs.readFileSync(path.join(root,'dist/core.js'),'utf8');assert(builtCore.includes("hour${hrs === 1 ? '' : 's'} per session"),'clean recurring-session duration label missing');assert(!builtCore.includes("hr${hrs === 1 ? '' : 's'} · £${total.toFixed(2)} per session"),'duplicate recurring-session price label remains');
console.log('Maintained runtime build tests passed.');
